code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long a;
    long long b;
    long long c;
    cin >> a >> b >> c;

    if (a + b <= c || a + c <= b || b + c <= a) {
        cout << "invalid" << endl;
    } else if (a == b && b == c) {
        cout << "equilateral" << endl;
    } else if (a == b || b == c || a == c) {
        cout << "isosceles" << endl;
    } else {
        cout << "scalene" << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long c = sc.nextLong();

        if (a + b <= c || a + c <= b || b + c <= a) {
            System.out.println("invalid");
        } else if (a == b && b == c) {
            System.out.println("equilateral");
        } else if (a == b || b == c || a == c) {
            System.out.println("isosceles");
        } else {
            System.out.println("scalene");
        }
    }
}
